export default {
	async Form_RegisteronSubmit() {
		try {
			// 1. Validar que las contraseñas coincidan
			if (Form_Register.sourceData.password !== Form_Register.sourceData.co_password) {
				showAlert("Las contraseñas no coinciden", "error");
				return; // Detiene el proceso si hay error
			}

			// 2. Ejecutar la API de registro (ApiRegister)
			await ApiRegister.run();

			// 3. Mostrar mensaje de éxito y redirigir a Login
			showAlert("¡Registro exitoso! Por favor inicia sesión", "success");
			navigateTo("Login"); // Redirige a la página de Login

		} catch (error) {
			// 4. Manejar errores (ej: correo ya registrado, campos inválidos)
			showAlert(ApiRegister.data?.message || "Error en el registro", "error");
		}
	}
};
